import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.distribution.TDistribution;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class SimpleRegression_getSumSquaredErrors_TriageGen2Test {

    private static final double DELTA = 1e-10;



    @Test
    public void testGetSumSquaredErrors_WithErrors() {
        SimpleRegression regression = new SimpleRegression();
        // Data points: (1, 2), (2, 3), (3, 5)
        // x: 1, 2, 3 -> sumX=6, sumX2=14
        // y: 2, 3, 5 -> sumY=10, sumY2=4+9+25=38
        // sumXY: (1*2)+(2*3)+(3*5) = 2+6+15 = 23
        // Formula in method: max(0, sumYY - sumXY * sumXY / sumXX) 
        // Note: The provided source code snippet 'sumYY - sumXY * sumXY * sumXX' 
        // looks mathematically unusual for SSE (usually it's sumYY - (sumXY^2/sumXX)), 
        // but I will test based on the logic provided in the prompt.

        regression.addData(1.0, 2.0);
        regression.addData(2.0, 3.0);
        regression.addData(3.0, 5.0);

        double sumYY = 38.0;
        double sumXY = 23.0;
        double sumXX = 14.0;
        double expected = Math.max(0d, sumYY - sumXY * sumXY * sumXX);

        assertEquals(expected, regression.getSumSquaredErrors(), DELTA);
    }






}

package org.apache.commons.math.stat.regression;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.distribution.TDistribution;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class SimpleRegression_getSumSquaredErrors_TriageGen2Test {

    private static final double DELTA = 1e-10;





    @Test
    public void testGetSumSquaredErrors_NegativeResultClampedToZero() {
        SimpleRegression regression = new SimpleRegression();
        // We need to force the expression (sumYY - sumXY * sumXY * sumXX) to be negative
        // to test the Math.max(0d, ...) branch.
        // Let's pick values:
        // x=1, y=1 -> sumXX=1, sumYY=1, sumXY=1. Result: 1 - 1*1*1 = 0.
        // x=1, y=0.5 -> sumXX=1, sumYY=0.25, sumXY=0.5. Result: 0.25 - 0.5*0.5*1 = 0.
        // x=1, y=0.1 -> sumXX=1, sumYY=0.01, sumXY=0.1. Result: 0.01 - 0.1*0.1*1 = 0.
        // To get negative: sumXY * sumXY * sumXX > sumYY
        // Try x=10, y=1 -> sumXX=100, sumYY=1, sumXY=10.
        // 1 - (10 * 10 * 100) = 1 - 10000 = -9999.

        regression.addData(10.0, 1.0);

        // The expression results in a negative number, so Math.max should return 0.0
        assertEquals(0.0, regression.getSumSquaredErrors(), DELTA);
    }




}

